class VSpaceRuntime {
  constructor(canvas){
    this.canvas=canvas;
    this.ctx=canvas.getContext("2d",{alpha:false});
    this.kind="sand";
    this.t=0;
    this.audio={energy:0,bass:0,mids:0,highs:0,onset:0};
    this.lastOnset=0;
    this.bloomEvents=[];
    this.bloomSeed=0;
    this.fieldBloomEvents=[];
    this.fieldLastPulse=-99;
    this.network=this.prepareNetwork();
    this.resize();
  }

  resize(){
    const dpr=Math.min(window.devicePixelRatio||1,2);
    const r=this.canvas.getBoundingClientRect();
    const w=Math.max(320,Math.round(r.width*dpr)),h=Math.max(320,Math.round(r.height*dpr));
    if(this.canvas.width!==w||this.canvas.height!==h){this.canvas.width=w;this.canvas.height=h}
  }

  setExperience(kind){
    this.kind=kind;this.t=0;this.bloomEvents=[];this.bloomSeed=0;
    this.fieldBloomEvents=[];this.fieldLastPulse=-99;
  }

  setAudio(a){
    this.audio=a;
    const trigger=a.onset>.42 && this.lastOnset<=.42;
    if(trigger){
      this.bloomSeed=(this.bloomSeed*37+29+Math.floor(a.bass*97)+Math.floor(a.highs*53))%this.network.points.length;
      this.bloomEvents.push({t:this.t,seed:this.bloomSeed,strength:Math.max(.55,a.onset)});
      if(this.bloomEvents.length>5)this.bloomEvents.shift();
    }
    this.lastOnset=a.onset;
  }

  prepareNetwork(){
    const points=VSPACE_DATA.network.p,edges=VSPACE_DATA.network.e;
    const adj=Array.from({length:points.length},()=>[]);
    for(const [a,b] of edges){adj[a].push(b);adj[b].push(a)}
    const hopCache=new Map();
    const hopsFrom=(seed)=>{
      if(hopCache.has(seed))return hopCache.get(seed);
      const d=Array(points.length).fill(99);d[seed]=0;const q=[seed];
      for(let qi=0;qi<q.length;qi++){
        const n=q[qi];for(const j of adj[n])if(d[j]===99){d[j]=d[n]+1;q.push(j)}
      }
      hopCache.set(seed,d);return d;
    };
    return {points,edges,adj,hopsFrom};
  }

  frame(dt){
    this.resize();this.t+=Math.min(dt,.05);
    const c=this.ctx,w=this.canvas.width,h=this.canvas.height;
    c.fillStyle="#000";c.fillRect(0,0,w,h);
    if(this.kind==="sand")this.drawSandFixed(c,w,h);
    else if(this.kind==="sand-floor")this.drawMoonPassageFloor(c,w,h);
    else this.drawNetwork(c,w,h,this.kind==="network-journey");
  }

  moonSlot(){
    const order=["v05","v03","v01","v02","v04"];
    const slot=Math.floor(this.t/10)%order.length;
    return {id:order[slot],next:order[(slot+1)%order.length],u:(this.t%10)/10,slot};
  }

  deformMoon(row,id,a,t){
    let x=row[0],y=row[1],z=row[2],ph=row[3],group=row[4],band=row[5],layer=row[6];
    const homeR=Math.hypot(x,y,z);
    // Keep the outer shell fixed; taper internal motion as it approaches the shell.
    if(homeR>=.98)return [x,y,z];
    const edge=Math.max(0,Math.min(1,(.98-homeR)/.08));
    const interior=edge*edge*(3-2*edge);
    // Local gains reflect measured browser levels, without changing the analyser.
    const bass=Math.max(0,Math.min(1,a.bass));
    const energy=Math.max(0,Math.min(1,a.energy*12));
    const mids=Math.max(0,Math.min(1,a.mids*14));
    const onset=Math.max(0,Math.min(1,a.onset*10));
    const pulse=Math.max(onset,energy*.55);
    if(id==="v05"){
      const sep=.025+.24*pulse+.22*bass;
      const g=(group%17)+1,ang=g*2.399963;
      x+=Math.cos(ang)*sep*(.35+.65*Math.sin(g*.7)**2);
      y+=Math.sin(ang)*sep*(.35+.65*Math.cos(g*.9)**2);
      z+=Math.sin(g*1.31)*sep*.75;
    }else if(id==="v03"){
      const layerWave=(layer%4-1.5)*(.012+.14*mids+.10*bass+.045*onset)*Math.sin(t*.75+ph);
      const r=homeR||1;
      x+=x/r*layerWave;y+=y/r*layerWave;z+=z/r*layerWave;
    }else if(id==="v01"){
      const rr=.014+.18*bass+.08*onset+.04*energy;
      const wave=Math.sin(ph*2.7+t*1.2)*rr;
      const r=homeR||1;
      x+=x/r*wave;y+=y/r*wave;z+=z/r*wave;
    }else if(id==="v02"){
      const cloud=(.012+.15*energy+.14*bass+.05*onset)*Math.sin(ph*4.0+t*.85);
      x+=Math.sin(ph*2.3+group*.31)*cloud;
      y+=Math.cos(ph*1.8+group*.47)*cloud;
      z+=Math.sin(ph*2.9+group*.23)*cloud;
    }else{
      const tang=(.010+.14*mids+.14*bass+.06*onset)*Math.sin(ph*3+t);
      const ox=x;x+=-y*tang;y+=ox*tang;
      z+=(.008+.055*bass+.03*energy)*Math.sin(ph*5+t*.7);
    }
    x=row[0]+(x-row[0])*interior;
    y=row[1]+(y-row[1])*interior;
    z=row[2]+(z-row[2])*interior;
    // Contain transformed material inside the fixed shell; no global breathing.
    const r=Math.hypot(x,y,z);
    if(r>.98){const limit=.98/r;x*=limit;y*=limit;z*=limit;}
    return [x,y,z];
  }

  drawMoonParticles(c,w,h,id,alpha=1,scaleFactor=1,offsetY=0){
    const t=this.t,pts=VSPACE_DATA.moon[id];

    const moonAudio=this.audio;

    const cx=w*.5,cy=h*(.5+offsetY),scale=Math.min(w,h)*.39*scaleFactor;
    const dpr=Math.min(window.devicePixelRatio||1,2);

    c.save();c.globalCompositeOperation="lighter";

    for(let i=0;i<pts.length;i++){
      const p=pts[i],q=this.deformMoon(p,id,moonAudio,t);
      const x=cx+q[0]*scale,y=cy+q[1]*scale;
      if(x<-4||x>w+4||y<-4||y>h+4)continue;

      const depth=Math.max(0,Math.min(1,(q[2]+1)*.5));

      // Stable high luminance: Moon must remain visible regardless of microphone level.
      const coreAlpha=alpha*(.62+.30*depth);
      const glowAlpha=alpha*(.085+.055*depth);
      const grain=.92*dpr;

      // Neutral white glow around each grain, independent of audio level.
      c.fillStyle=`rgba(255,255,255,${glowAlpha})`;
      c.fillRect(x-grain*.85,y-grain*.85,grain*2.7,grain*2.7);

      c.fillStyle=`rgba(255,255,255,${coreAlpha})`;
      c.fillRect(x,y,grain,grain);

      // One extra deterministic micro-grain per source particle: visually doubles
      // density without changing the authoritative source geometry.
      const h1=((i*1103515245+12345)>>>8)&255;
      const h2=((i*2654435761+1013904223)>>>9)&255;
      const ox=((h1/255)-.5)*1.65*dpr;
      const oy=((h2/255)-.5)*1.65*dpr;
      c.fillStyle=`rgba(255,255,255,${coreAlpha*.52})`;
      c.fillRect(x+ox,y+oy,grain*.72,grain*.72);
    }
    c.restore();
  }

  drawSandFixed(c,w,h){
    const s=this.moonSlot();
    // Same center and same normalized radius for every form; camera is completely fixed.
    const fade=.10;
    if(s.u>1-fade){
      const q=(s.u-(1-fade))/fade;
      this.drawMoonParticles(c,w,h,s.id,1-q,1,0);
      this.drawMoonParticles(c,w,h,s.next,q,1,0);
    }else{
      this.drawMoonParticles(c,w,h,s.id,1,1,0);
    }
  }

  floorProject(x,z,w,h){
    const horizon=h*.61,forward=z+5.5;
    if(forward<.22)return null;
    const inv=1/forward;
    return [w*.5+x*w*.78*inv,horizon+(h-horizon)*2.25*inv,inv];
  }

  drawTileFloor(c,w,h){
    const a=this.audio,t=this.t;
    const impact=Math.min(1.5,a.onset*1.8+a.energy*.65);

    // Moon + Floor: the floor is an endless world surface under the camera.
    // Rows travel FROM the horizon TOWARD / THROUGH the viewer, then recycle
    // at the far end. This creates continuous forward passage rather than
    // making the floor look like a static stage beneath the Moon.
    const rowStep=.72;
    const local=t%10;
    const inPassage=local>=4.5;
    const passageBoost=inPassage ? .34 : 0;
    const speed=.42+.46*a.energy+passageBoost;
    const travel=t*speed;
    const phase=travel%rowStep;

    c.save();c.globalCompositeOperation="lighter";

    // Extend both toward the horizon and through the lower frame edge.
    // Negative rows are the near-camera floor; clipping by the canvas makes the
    // surface feel continuous beyond the viewer rather than ending mid-frame.
    for(let rz=-6;rz<22;rz++){
      const z=rz*rowStep-phase;

      for(let col=-15;col<=15;col++){
        const x=col*.72;
        const p1=this.floorProject(x-.28,z,w,h),p2=this.floorProject(x+.28,z,w,h),
              p3=this.floorProject(x+.28,z+.48,w,h),p4=this.floorProject(x-.28,z+.48,w,h);
        if(!p1||!p2||!p3||!p4)continue;

        c.beginPath();
        c.moveTo(p1[0],p1[1]);c.lineTo(p2[0],p2[1]);
        c.lineTo(p3[0],p3[1]);c.lineTo(p4[0],p4[1]);c.closePath();
        c.strokeStyle=`rgba(164,145,108,${.16+.32*impact})`;
        c.lineWidth=Math.max(1,1.1*window.devicePixelRatio);
        c.stroke();

        if((rz+col)%3===0){
          const cx=(p2[0]+p3[0])/2,cy=(p2[1]+p3[1])/2,rr=3+10*impact;
          c.fillStyle=`rgba(151,72,63,${.12+.25*impact})`;
          c.save();c.translate(cx,cy);c.rotate(Math.PI/4);
          c.fillRect(-rr/2,-rr/2,rr,rr);c.restore();
        }
      }

      if(rz%4===3){
        const a1=this.floorProject(-11,z+.58,w,h),a2=this.floorProject(11,z+.58,w,h),
              a3=this.floorProject(11,z+.69,w,h),a4=this.floorProject(-11,z+.69,w,h);
        if(a1&&a2&&a3&&a4){
          c.beginPath();c.moveTo(a1[0],a1[1]);c.lineTo(a2[0],a2[1]);
          c.lineTo(a3[0],a3[1]);c.lineTo(a4[0],a4[1]);c.closePath();
          c.fillStyle=`rgba(120,58,53,${.08+.16*impact})`;c.fill();
        }
      }
    }
    c.restore();
  }

  drawMoonPassageFloor(c,w,h){
    this.drawTileFloor(c,w,h);
    const s=this.moonSlot(),local=this.t%10;
    // 0-4.5 observe, then canonical 5.5s passage to next form.
    if(local<4.5){
      this.drawMoonParticles(c,w,h,s.id,1,.92,-.10);
      return;
    }
    const p=(local-4.5)/5.5;
    // approach 1.8, cover .5, crossfade 1.2, reveal 2.0
    if(p<1.8/5.5){
      const u=p/(1.8/5.5);
      this.drawMoonParticles(c,w,h,s.id,1,.92+1.45*u,-.10);
    }else if(p<(2.3/5.5)){
      this.drawMoonParticles(c,w,h,s.id,.95,2.37,-.10);
    }else if(p<(3.5/5.5)){
      const u=(p-2.3/5.5)/(1.2/5.5);
      this.drawMoonParticles(c,w,h,s.id,1-u,2.2-.6*u,-.10);
      this.drawMoonParticles(c,w,h,s.next,u,.68+.52*u,-.10);
    }else{
      const u=(p-3.5/5.5)/(2.0/5.5);
      this.drawMoonParticles(c,w,h,s.next,1,1.2-.28*u,-.10);
    }
  }

  networkView(p,w,h,journey){
    let x=p[0],y=p[1],z=p[2];
    if(journey){
      const cycle=this.t%48;
      let yaw=0,zoom=1,tx=0;
      if(cycle<8){const u=cycle/8;yaw=.34*u;zoom=1+.32*u;tx=.12*u}
      else if(cycle<20){yaw=.34;zoom=1.32;tx=.12}
      else if(cycle<28){const u=(cycle-20)/8;yaw=.34+.20*u;zoom=1.32-.22*u;tx=.12-.17*u}
      else if(cycle<40){yaw=.54;zoom=1.10;tx=-.05}
      else {const u=(cycle-40)/8;yaw=.54*(1-u);zoom=1.10-.10*u;tx=-.05*(1-u)}
      const cy=Math.cos(yaw),sy=Math.sin(yaw);
      const xx=x*cy-z*sy,zz=x*sy+z*cy;x=(xx-tx)*zoom;z=zz*zoom;
    }
    const scale=Math.min(w,h)*.43;
    return [w*.5+x*scale,h*.5+y*scale,z];
  }

  nodeExcitation(i){
    let ex=0;
    for(const ev of this.bloomEvents){
      const age=this.t-ev.t;if(age<0||age>8)continue;
      const hops=this.network.hopsFrom(ev.seed)[i];
      const front=age*2.15;
      const d=Math.abs(hops-front);
      ex+=Math.exp(-d*d/.85)*Math.exp(-age*.085)*ev.strength;
      ex+=.16*Math.exp(-hops*.42)*Math.exp(-age*.35)*ev.strength;
    }
    return Math.min(2.6,ex);
  }

  fieldSensitiveState(){
    // Irregular repeating rhythm: quiet 5–10s, sensitive 10–20s.
    const spans=[
      [6,false],[14,true],
      [8,false],[18,true],
      [5,false],[12,true],
      [9,false],[16,true]
    ];
    const total=spans.reduce((s,x)=>s+x[0],0);
    let local=this.t%total;
    for(const [duration,sensitive] of spans){
      if(local<duration)return {sensitive,local,duration};
      local-=duration;
    }
    return {sensitive:false,local:0,duration:6};
  }

  updateFieldBloom(){
    const state=this.fieldSensitiveState();
    if(!state.sensitive)return state;

    // Much lower activation threshold than the old onset-only trigger.
    const a=this.audio;
    const signal=Math.min(1, a.energy*.55+a.bass*.18+a.mids*.22+a.highs*.18+a.onset*.85);
    const interval=1.35-.55*Math.min(1,signal*2.4);

    if(signal>.055 && this.t-this.fieldLastPulse>=interval){
      this.fieldLastPulse=this.t;
      this.bloomSeed=(this.bloomSeed*41+31+
        Math.floor(a.bass*173)+Math.floor(a.mids*109)+Math.floor(this.t*7)
      )%this.network.points.length;

      // Sensitive window deliberately exaggerates the halo response.
      const strength=1.25+Math.min(2.4,signal*4.8);
      this.fieldBloomEvents.push({t:this.t,seed:this.bloomSeed,strength});
      if(this.fieldBloomEvents.length>12)this.fieldBloomEvents.shift();
    }
    this.fieldBloomEvents=this.fieldBloomEvents.filter(ev=>this.t-ev.t<10);
    return state;
  }

  fieldExcitation(i){
    let ex=0;
    for(const ev of this.fieldBloomEvents){
      const age=this.t-ev.t;if(age<0||age>9)continue;
      const hops=this.network.hopsFrom(ev.seed)[i];
      const front=age*2.0;
      const d=Math.abs(hops-front);
      // Broad traveling halo front + softer lingering wake.
      ex+=Math.exp(-d*d/1.25)*Math.exp(-age*.060)*ev.strength;
      ex+=.22*Math.exp(-hops*.34)*Math.exp(-age*.22)*ev.strength;
    }
    return Math.min(4.5,ex);
  }

  drawNetwork(c,w,h,journey){
    const a=this.audio;

    // JOURNEY: establish wide, move into detail, hold, pull out, pause, then repeat
    // from a different deterministic interior target/angle. No hard cuts.
    if(journey){
      const points=this.network.points,edges=this.network.edges;
      const transformed=[];

      const ease=(u)=>u*u*(3-2*u);
      const cycleLen=95;
      const cycle=this.t%cycleLen;
      const pass=Math.floor(this.t/cycleLen)%4;

      // Four repeatable interior target viewpoints. They feel varied but remain bounded.
      const views=[
        {yaw:.48,pitch:.18,camNear:1.08,tx:.22,ty:-.09},
        {yaw:-.56,pitch:-.14,camNear:1.18,tx:-.21,ty:.12},
        {yaw:.72,pitch:-.20,camNear:.98,tx:.16,ty:.15},
        {yaw:-.38,pitch:.22,camNear:1.12,tx:-.14,ty:-.13}
      ];
      const v=views[pass];

      let yaw=0,pitch=0,camZ=3.78,tx=0,ty=0;

      if(cycle < 15){
        // 0–15s: wide establishing observation
        const u=cycle/15;
        yaw=.025*Math.sin(u*Math.PI);
        pitch=.012*Math.sin(u*Math.PI*1.3);
      }else if(cycle < 25){
        // 15–25s: true forward travel into the construction.
        // Geometry is intentionally allowed to leave multiple frame edges.
        const u=ease((cycle-15)/10);
        yaw=v.yaw*u; pitch=v.pitch*u;
        camZ=3.78+(v.camNear-3.78)*u;
        tx=v.tx*u; ty=v.ty*u;
      }else if(cycle < 38){
        // 25–38s: stop inside and observe one detail.
        yaw=v.yaw; pitch=v.pitch; camZ=v.camNear; tx=v.tx; ty=v.ty;
      }else if(cycle < 50){
        // 38–50s: long smooth retreat until the network becomes whole again.
        const u=ease((cycle-38)/12);
        yaw=v.yaw*(1-u*.82); pitch=v.pitch*(1-u*.82);
        camZ=v.camNear+(3.68-v.camNear)*u;
        tx=v.tx*(1-u*.90); ty=v.ty*(1-u*.90);
      }else if(cycle < 60){
        // 50–60s: wide pause.
        const u=(cycle-50)/10;
        yaw=v.yaw*.18*(1-u); pitch=v.pitch*.18*(1-u);
        camZ=3.68+.08*u;
        tx=v.tx*.10*(1-u); ty=v.ty*.10*(1-u);
      }else if(cycle < 70){
        // 60–70s: second deep entry from another angle.
        const next=views[(pass+1)%views.length];
        const u=ease((cycle-60)/10);
        yaw=next.yaw*u; pitch=next.pitch*u;
        camZ=3.76+(next.camNear-3.76)*u;
        tx=next.tx*u; ty=next.ty*u;
      }else if(cycle < 83){
        // 70–83s: hold second interior detail.
        const next=views[(pass+1)%views.length];
        yaw=next.yaw; pitch=next.pitch; camZ=next.camNear; tx=next.tx; ty=next.ty;
      }else{
        // 83–95s: smooth pull out.
        const next=views[(pass+1)%views.length];
        const u=ease((cycle-83)/12);
        yaw=next.yaw*(1-u); pitch=next.pitch*(1-u);
        camZ=next.camNear+(3.78-next.camNear)*u;
        tx=next.tx*(1-u); ty=next.ty*(1-u);
      }

      const scale=Math.min(w,h)*.54;
      for(let i=0;i<points.length;i++){
        const p=points[i], drift=.018+.055*a.mids+.028*a.energy;
        const breathe=1+.035*a.energy+.045*a.bass;
        const cy=Math.cos(yaw),sy=Math.sin(yaw);
        let x=(p[0]+Math.sin(this.t*.11+i*.93)*drift)*breathe;
        let y=(p[1]+Math.cos(this.t*.085+i*.57)*drift)*breathe;
        let z=p[2]*breathe;
        let x1=x*cy-z*sy,z1=x*sy+z*cy;
        const cx=Math.cos(pitch),sx=Math.sin(pitch);
        let y1=y*cx-z1*sx,z2=y*sx+z1*cx;
        const zz=z2+camZ;
        const pr=1/Math.max(.18,zz);
        const depthBoost=journey ? Math.max(.92,Math.min(2.7,3.0/camZ)) : 1;
        transformed.push([
          w*.5+(x1-tx)*scale*pr*camZ*depthBoost,
          h*.5+(y1-ty)*scale*pr*camZ*depthBoost,
          zz
        ]);
      }

      c.save();c.globalCompositeOperation="lighter";
      for(const [i,j] of edges){
        const p=transformed[i],q=transformed[j]; if(!p||!q||p[2]<.3||q[2]<.3)continue;
        const shimmer=.5+.5*Math.sin(this.t*.75+i*.31+j*.17);
        const intensity=Math.min(1.5,.16+1.05*a.mids+.35*a.energy+.25*shimmer);
        c.strokeStyle=`rgba(226,202,147,${Math.min(.58,.07+.24*intensity)})`;
        c.lineWidth=Math.max(1,(.7+.9*intensity)*(window.devicePixelRatio||1));
        c.beginPath();c.moveTo(p[0],p[1]);c.lineTo(q[0],q[1]);c.stroke();
      }
      for(let i=0;i<transformed.length;i++){
        const p=transformed[i];if(p[2]<.3)continue;
        const sparkle=.5+.5*Math.sin(this.t*(1.2+.8*a.highs)+i*1.37);
        const intensity=Math.min(1.4,.22+.55*sparkle+1.05*a.highs+.35*a.energy);
        const r=(.75+1.8*intensity)*Math.min(window.devicePixelRatio||1,2);
        const g=c.createRadialGradient(p[0],p[1],0,p[0],p[1],r*5);
        g.addColorStop(0,`rgba(255,235,185,${Math.min(.9,.42+.25*intensity)})`);
        g.addColorStop(.16,`rgba(255,210,125,${Math.min(.55,.14+.22*intensity)})`);
        g.addColorStop(1,"rgba(160,105,40,0)");
        c.fillStyle=g;c.beginPath();c.arc(p[0],p[1],r*5,0,Math.PI*2);c.fill();
        c.fillStyle=`rgba(255,236,190,${Math.min(.95,.5+.25*intensity)})`;
        c.beginPath();c.arc(p[0],p[1],Math.max(1,r),0,Math.PI*2);c.fill();
      }
      c.restore();
      return;
    }

    // FIELD: fixed geometry and camera. Only the luminous halo breathes and propagates.
    const P=this.network.points.map(p=>this.networkView(p,w,h,false));
    const fieldState=this.updateFieldBloom();
    const sensitivity=fieldState.sensitive ? 1 : 0;

    c.save();c.globalCompositeOperation="lighter";

    // Connection geometry remains a thin, stable drawing.
    for(const [i,j] of this.network.edges){
      const p=P[i],q=P[j];
      const ex=Math.max(this.fieldExcitation(i),this.fieldExcitation(j));

      c.strokeStyle="rgba(232,205,145,.105)";
      c.lineWidth=Math.max(1,.72*Math.min(window.devicePixelRatio||1,2));
      c.beginPath();c.moveTo(p[0],p[1]);c.lineTo(q[0],q[1]);c.stroke();

      // Keep connection glow thread-like: several translucent, round, uneven
      // wisps around the stable line rather than one thick luminous bar.
      if(ex>.10){
        const dpr=Math.min(window.devicePixelRatio||1,2);
        const dx=q[0]-p[0],dy=q[1]-p[1],len=Math.max(1,Math.hypot(dx,dy));
        const nx=-dy/len,ny=dx/len;
        const pulse=.62+.38*Math.sin(this.t*1.15+i*.73+j*.31);
        const thread=Math.min(1,ex*.34)*sensitivity;

        c.lineCap="round";
        for(let k=0;k<4;k++){
          const phase=this.t*(.22+.035*k)+i*.61+j*.27+k*1.9;
          const offset=Math.sin(phase)*(1.3+1.25*k)*dpr;
          const alpha=(.030+.028*thread)*(.62+.38*Math.sin(phase*1.7))*pulse;
          c.strokeStyle=`rgba(235,177,82,${Math.max(0,alpha)})`;
          c.lineWidth=(1.8+k*1.55+ex*.42)*dpr;
          c.beginPath();
          c.moveTo(p[0]+nx*offset,p[1]+ny*offset);
          c.lineTo(q[0]+nx*offset,q[1]+ny*offset);
          c.stroke();
        }

        // A faint smoky envelope, deliberately weak and narrow.
        c.strokeStyle=`rgba(205,135,58,${Math.min(.055,.010+ex*.009*sensitivity)})`;
        c.lineWidth=(7+ex*1.8)*dpr;
        c.beginPath();c.moveTo(p[0],p[1]);c.lineTo(q[0],q[1]);c.stroke();
      }
    }

    for(let i=0;i<P.length;i++){
      const p=P[i],ex=this.fieldExcitation(i);

      // Fixed-size star/core. Audio never enlarges the physical point.
      const dpr=Math.min(window.devicePixelRatio||1,2);
      const coreRadius=1.45*dpr;

      // Round halo: ~90% previous radius and ~70% previous brightness.
      // Multiple radial layers create a soft smoky edge without changing core size.
      if(ex>.06){
        const radius=(10.8+ex*25.2)*dpr;
        const alpha=Math.min(.644,(.077+ex*.119)*sensitivity);
        const g=c.createRadialGradient(p[0],p[1],0,p[0],p[1],radius);
        g.addColorStop(0,`rgba(255,235,185,${alpha})`);
        g.addColorStop(.08,`rgba(255,207,118,${Math.min(.50,alpha*.68)})`);
        g.addColorStop(.28,`rgba(241,176,78,${Math.min(.27,alpha*.34)})`);
        g.addColorStop(.58,`rgba(210,137,53,${Math.min(.11,alpha*.14)})`);
        g.addColorStop(.82,`rgba(180,105,38,${Math.min(.045,alpha*.055)})`);
        g.addColorStop(1,"rgba(150,82,25,0)");
        c.fillStyle=g;c.beginPath();c.arc(p[0],p[1],radius,0,Math.PI*2);c.fill();

        const smokeR=radius*(1.04+.035*Math.sin(this.t*.37+i*1.13));
        const sg=c.createRadialGradient(p[0],p[1],radius*.22,p[0],p[1],smokeR);
        sg.addColorStop(0,"rgba(224,154,68,0)");
        sg.addColorStop(.48,`rgba(213,142,58,${Math.min(.035,ex*.006*sensitivity)})`);
        sg.addColorStop(.76,`rgba(185,112,42,${Math.min(.022,ex*.004*sensitivity)})`);
        sg.addColorStop(1,"rgba(150,82,25,0)");
        c.fillStyle=sg;c.beginPath();c.arc(p[0],p[1],smokeR,0,Math.PI*2);c.fill();
      }

      // Constant point size and nearly constant core brightness.
      c.fillStyle="rgba(255,234,184,.82)";
      c.beginPath();c.arc(p[0],p[1],coreRadius,0,Math.PI*2);c.fill();
    }
    c.restore();
  }
}
window.VSpaceRuntime=VSpaceRuntime;
